Unify the three existing skipOps variants (PyTorch / Functorch / DTensor), make them fully compatible with instantiate_device_type_tests, and improve the current usage of @SkipOps.
# New interface
def skipOps(to_skip):
    def wrapped(fn):
        fn._skipops = tuple(to_skip)
        return fn
    return wrapped

